import type { ApiResult, SkillFragment } from "./_lib/contracts";
import { createServiceRoleClient, type OperatorKitEnv } from "./_lib/supabaseClient";

export interface CreateSkillInput {
 userId: string;
 name: string;
 description: string;
 domain: SkillFragment["domain"];
 instructions?: string;
 active?: boolean;
 metadata?: Record<string, unknown>;
}

function mapSkillFragment(row: Record<string, unknown>): SkillFragment {
 return {
 id: String(row.id),
 userId: String(row.user_id),
 name: String(row.name),
 description: String(row.description),
 domain: row.domain as SkillFragment["domain"],
 instructions: row.instructions ? String(row.instructions) : null,
 active: Boolean(row.active),
 metadata: (row.metadata as Record<string, unknown>) ?? {}
 };
}

function asApiError(error: { message?: string; code?: string } | null) {
 if (!error) {
 return null;
 }

 return {
 message: error.message ?? "Unknown Supabase error.",
 code: error.code
 };
}

export async function listSkills(
 env: OperatorKitEnv,
 userId: string
): Promise<ApiResult<SkillFragment[]>> {
 const supabase = createServiceRoleClient(env);
 const { data, error } = await supabase
 .from("skill_fragments")
 .select("*")
 .eq("user_id", userId)
 .is("deleted_at", null)
 .order("created_at", { ascending: false });

 if (error) {
 return { data: null, error: asApiError(error) };
 }

 return {
 data: (data ?? []).map((row) => mapSkillFragment(row as Record<string, unknown>)),
 error: null
 };
}

export async function createSkill(
 env: OperatorKitEnv,
 input: CreateSkillInput
): Promise<ApiResult<SkillFragment>> {
 const supabase = createServiceRoleClient(env);
 const { data, error } = await supabase
 .from("skill_fragments")
 .insert({
 user_id: input.userId,
 name: input.name,
 description: input.description,
 domain: input.domain,
 instructions: input.instructions ?? null,
 active: input.active ?? true,
 metadata: input.metadata ?? {}
 })
 .select("*")
 .single();

 if (error) {
 return { data: null, error: asApiError(error) };
 }

 return { data: mapSkillFragment(data as Record<string, unknown>), error: null };
}

export async function updateSkill(
 env: OperatorKitEnv,
 skillId: string,
 patch: Partial<CreateSkillInput>
): Promise<ApiResult<SkillFragment>> {
 const supabase = createServiceRoleClient(env);
 const { data, error } = await supabase
 .from("skill_fragments")
 .update({
 name: patch.name,
 description: patch.description,
 domain: patch.domain,
 instructions: patch.instructions,
 active: patch.active,
 metadata: patch.metadata
 })
 .eq("id", skillId)
 .select("*")
 .single();

 if (error) {
 return { data: null, error: asApiError(error) };
 }

 return { data: mapSkillFragment(data as Record<string, unknown>), error: null };
}

export async function softDeleteSkill(
 env: OperatorKitEnv,
 skillId: string
): Promise<ApiResult<{ id: string }>> {
 const supabase = createServiceRoleClient(env);
 const { error } = await supabase
 .from("skill_fragments")
 .update({ deleted_at: new Date().toISOString() })
 .eq("id", skillId);

 if (error) {
 return { data: null, error: asApiError(error) };
 }

 return { data: { id: skillId }, error: null };
}

import type { ApiResult, VocabularyProfile } from "./_lib/contracts";
import { createServiceRoleClient, type OperatorKitEnv } from "./_lib/supabaseClient";

export interface UpsertVocabularyProfileInput {
 userId: string;
 vocabulary: string[];
 tone: string;
 constraints: string[];
 metadata?: Record<string, unknown>;
}

function asApiError(error: { message?: string; code?: string } | null) {
 if (!error) {
 return null;
 }

 return {
 message: error.message ?? "Unknown Supabase error.",
 code: error.code
 };
}

function mapProfile(row: Record<string, unknown>): VocabularyProfile {
 return {
 id: String(row.id),
 userId: String(row.user_id),
 vocabulary: ((row.vocabulary as unknown[]) ?? []).map((item) => String(item)),
 tone: String(row.tone ?? "clear"),
 constraints: ((row.constraints as unknown[]) ?? []).map((item) => String(item)),
 metadata: (row.metadata as Record<string, unknown>) ?? {}
 };
}

export async function getVocabularyProfile(
 env: OperatorKitEnv,
 userId: string
): Promise<ApiResult<VocabularyProfile>> {
 const supabase = createServiceRoleClient(env);
 const { data, error } = await supabase
 .from("plk_profiles")
 .select("*")
 .eq("user_id", userId)
 .is("deleted_at", null)
 .single();

 if (error) {
 return { data: null, error: asApiError(error) };
 }

 return { data: mapProfile(data as Record<string, unknown>), error: null };
}

export async function upsertVocabularyProfile(
 env: OperatorKitEnv,
 input: UpsertVocabularyProfileInput
): Promise<ApiResult<VocabularyProfile>> {
 const supabase = createServiceRoleClient(env);
 const payload = {
 user_id: input.userId,
 vocabulary: input.vocabulary,
 tone: input.tone,
 constraints: input.constraints,
 metadata: input.metadata ?? {}
 };

 const { data, error } = await supabase
 .from("plk_profiles")
 .upsert(payload, { onConflict: "user_id" })
 .select("*")
 .single();

 if (error) {
 return { data: null, error: asApiError(error) };
 }

 return { data: mapProfile(data as Record<string, unknown>), error: null };
}

import { operatorPacks } from "../config/operatorPacks";
import {
 createImportManifestTemplate,
 type ImportManifestTemplate
} from "../config/importTemplates";
import { sourceBundles } from "../config/sourceBundles";
import type {
 ApiResult,
 PackRouteRequest,
 StarterPackApplication,
 StarterPackExecutionResult,
 StarterPackPreview
} from "./_lib/contracts";
import { createServiceRoleClient, type OperatorKitEnv } from "./_lib/supabaseClient";

export interface ApplyStarterPackInput {
 userId: string;
 packSlug: string;
 selectedBundleSlugs?: string[];
 projectName?: string;
 owner?: string;
}

export interface StarterPackPlan {
 packSlug: string;
 title: string;
 selectedSourceBundles: string[];
 generatedSkills: string[];
 generatedMemoryKeys: string[];
 recommendedSourceBundles: string[];
 nextActions: string[];
}

type PackRouteResponseData =
 | StarterPackPreview[]
 | typeof sourceBundles
 | StarterPackPreview
 | StarterPackPlan
 | ImportManifestTemplate
 | StarterPackExecutionResult;

const generatedSkillMap: Record<string, string[]> = {
 "general-operator-foundation": [
 "Ground answers in uploaded corpus.",
 "Prefer direct, useful outputs over generic assistant filler."
 ],
 "devops-terminal-pack": [
 "Support terminal-first operators with inspectable commands.",
 "Prefer concrete operational checks over vague setup prose."
 ],
 "agent-source-starter-bundle": [
 "Study source bundles before authoring new assistant behavior.",
 "Bias toward explicit reference material over generic prompt synthesis."
 ],
 "persistent-memory-foundation": [
 "Keep continuity legible and bounded.",
 "Separate user, shared, and pinned memory concerns."
 ]
};

const generatedMemoryMap: Record<string, string[]> = {
 "general-operator-foundation": ["operator_preference_style"],
 "devops-terminal-pack": ["operator_prefers_cli"],
 "agent-source-starter-bundle": ["study_before_write"],
 "persistent-memory-foundation": ["shared_memory_model", "pinned_continuity_rules"]
};

const recommendedBundleMap: Record<string, string[]> = {
 "general-operator-foundation": ["knowledge-core-bundle", "context-alignment-bundle"],
 "devops-terminal-pack": ["code-context-bundle"],
 "agent-source-starter-bundle": [
 "knowledge-core-bundle",
 "code-context-bundle",
 "product-ops-bundle",
 "context-alignment-bundle"
 ],
 "persistent-memory-foundation": ["context-alignment-bundle"]
};

function asApiError(error: { message?: string; code?: string } | null) {
 if (!error) {
 return null;
 }

 return {
 message: error.message ?? "Unknown Supabase error.",
 code: error.code
 };
}

export function previewStarterPacks(): StarterPackPreview[] {
 return operatorPacks.map((pack) => ({
 slug: pack.slug,
 title: pack.title,
 kind: pack.kind,
 summary: pack.summary,
 recommendedSourceBundles: recommendedBundleMap[pack.slug] ?? [],
 generatedSkills: generatedSkillMap[pack.slug] ?? [],
 generatedMemoryKeys: generatedMemoryMap[pack.slug] ?? []
 }));
}

export function listSourceBundles() {
 return sourceBundles;
}

export function findStarterPackPreview(packSlug: string): StarterPackPreview | null {
 return previewStarterPacks().find((pack) => pack.slug === packSlug) ?? null;
}

function normalizeSelectedBundleSlugs(
 packSlug: string,
 selectedBundleSlugs?: string[]
): string[] {
 const fallback = recommendedBundleMap[packSlug] ?? [];
 const requested = selectedBundleSlugs && selectedBundleSlugs.length > 0
 ? selectedBundleSlugs
 : fallback;

 return requested.filter((bundleSlug, index) => {
 const exists = sourceBundles.some((bundle) => bundle.slug === bundleSlug);
 return exists && requested.indexOf(bundleSlug) === index;
 });
}

export function buildStarterPackPlan(
 packSlug: string,
 selectedBundleSlugs?: string[]
): ApiResult<StarterPackPlan> {
 const preview = findStarterPackPreview(packSlug);

 if (!preview) {
 return {
 data: null,
 error: {
 message: `Unknown starter pack: ${packSlug}`,
 code: "starter_pack_not_found"
 }
 };
 }

 const chosenBundles = normalizeSelectedBundleSlugs(packSlug, selectedBundleSlugs);

 return {
 data: {
 packSlug,
 title: preview.title,
 selectedSourceBundles: chosenBundles,
 generatedSkills: preview.generatedSkills,
 generatedMemoryKeys: preview.generatedMemoryKeys,
 recommendedSourceBundles: preview.recommendedSourceBundles,
 nextActions: [
 "Apply the starter pack to seed generic skills and memory posture.",
 "Load buyer-owned material into the selected source bundles only.",
 "Generate and refine the import manifest before ingesting real corpus files."
 ]
 },
 error: null
 };
}

export function buildImportManifestForPack(
 packSlug: string,
 projectName = "replace-with-project-name",
 owner = "replace-with-owner",
 selectedBundleSlugs?: string[]
): ApiResult<ImportManifestTemplate> {
 const planResult = buildStarterPackPlan(packSlug, selectedBundleSlugs);

 if (!planResult.data || planResult.error) {
 return {
 data: null,
 error: planResult.error
 };
 }

 const template = createImportManifestTemplate();

 return {
 data: {
 ...template,
 projectName,
 owner,
 entries: planResult.data.selectedSourceBundles.map((bundleSlug, index) => {
 const bundle = sourceBundles.find((entry) => entry.slug === bundleSlug);

 return {
 title: bundle?.title ?? `replace-with-document-title-${index + 1}`,
 lane: bundle?.lane ?? "knowledge",
 sourceType: "file" as const,
 sourceUri: `./path/to/your-${bundle?.lane ?? "knowledge"}-source-${index + 1}.md`,
 audience: "internal",
 notes: bundle
 ? `Buyer-owned source for ${bundle.title}. Replace with your own material only.`
 : "Buyer-owned source. Replace with your own material only."
 };
 })
 },
 error: null
 };
}

export function buildStarterPackRouteRequest(input: {
 packSlug: string;
 userId: string;
 selectedBundleSlugs?: string[];
 projectName?: string;
 owner?: string;
}): PackRouteRequest {
 return {
 method: "POST",
 action: "apply",
 packSlug: input.packSlug,
 userId: input.userId,
 selectedBundleSlugs: input.selectedBundleSlugs,
 projectName: input.projectName,
 owner: input.owner
 };
}

export async function handlePacksRoute(
 request: PackRouteRequest
): Promise<ApiResult<PackRouteResponseData>> {
 switch (request.action) {
 case "list":
 return {
 data: previewStarterPacks(),
 error: null
 };
 case "bundles":
 return {
 data: listSourceBundles(),
 error: null
 };
 case "preview":
 if (!request.packSlug) {
 return {
 data: null,
 error: {
 message: "packSlug is required for preview.",
 code: "missing_pack_slug"
 }
 };
 }

 return {
 data: findStarterPackPreview(request.packSlug),
 error: findStarterPackPreview(request.packSlug)
 ? null
 : {
 message: `Unknown starter pack: ${request.packSlug}`,
 code: "starter_pack_not_found"
 }
 };
 case "plan":
 if (!request.packSlug) {
 return {
 data: null,
 error: {
 message: "packSlug is required for plan.",
 code: "missing_pack_slug"
 }
 };
 }

 return buildStarterPackPlan(request.packSlug, request.selectedBundleSlugs);
 case "manifest":
 if (!request.packSlug) {
 return {
 data: null,
 error: {
 message: "packSlug is required for manifest.",
 code: "missing_pack_slug"
 }
 };
 }

 return buildImportManifestForPack(
 request.packSlug,
 request.projectName,
 request.owner,
 request.selectedBundleSlugs
 );
 case "apply":
 return {
 data: null,
 error: {
 message:
 "Pack application requires an environment-backed handler. Use handlePacksRouteWithEnv or the apply-pack script.",
 code: "env_required_for_apply"
 }
 };
 default:
 return {
 data: null,
 error: {
 message: `Unsupported action: ${request.action satisfies never}`,
 code: "unsupported_action"
 }
 };
 }
}

export async function applyStarterPack(
 env: OperatorKitEnv,
 input: ApplyStarterPackInput
): Promise<ApiResult<StarterPackApplication>> {
 const pack = operatorPacks.find((entry) => entry.slug === input.packSlug);

 if (!pack) {
 return {
 data: null,
 error: {
 message: `Unknown starter pack: ${input.packSlug}`,
 code: "starter_pack_not_found"
 }
 };
 }

 const supabase = createServiceRoleClient(env);
 const generatedSkills = generatedSkillMap[pack.slug] ?? [];
 const generatedMemoryKeys = generatedMemoryMap[pack.slug] ?? [];
 const recommendedBundles = recommendedBundleMap[pack.slug] ?? [];

 if (generatedSkills.length > 0) {
 const { error: skillsError } = await (supabase.from("skill_fragments") as any).insert(
 generatedSkills.map((description, index) => ({
 user_id: input.userId,
 name: `${pack.title} Skill ${index + 1}`,
 description,
 domain: "general",
 active: true,
 metadata: {
 starter_pack: pack.slug,
 generated: true
 }
 }))
 );

 if (skillsError) {
 return {
 data: null,
 error: asApiError(skillsError)
 };
 }
 }

 if (generatedMemoryKeys.length > 0) {
 const { error: memoryError } = await (supabase.from("memory_entries") as any).insert(
 generatedMemoryKeys.map((memoryKey) => ({
 user_id: input.userId,
 session_id: `starter-pack:${pack.slug}`,
 key: memoryKey,
 value: {
 source: "starter_pack",
 pack: pack.slug
 },
 importance: 3,
 metadata: {
 starter_pack: pack.slug,
 scope: memoryKey.includes("shared") ? "shared" : "user",
 pinned: memoryKey.includes("pinned")
 }
 }))
 );

 if (memoryError) {
 return {
 data: null,
 error: asApiError(memoryError)
 };
 }
 }

 return {
 data: {
 packSlug: pack.slug,
 activatedSkills: generatedSkills,
 seededMemoryKeys: generatedMemoryKeys,
 recommendedSourceBundles: normalizeSelectedBundleSlugs(
 pack.slug,
 input.selectedBundleSlugs ?? recommendedBundles
 )
 },
 error: null
 };
}

export async function executeStarterPackActivation(
 env: OperatorKitEnv,
 input: ApplyStarterPackInput
): Promise<ApiResult<StarterPackExecutionResult>> {
 const applicationResult = await applyStarterPack(env, input);

 if (!applicationResult.data || applicationResult.error) {
 return {
 data: null,
 error: applicationResult.error
 };
 }

 const manifestResult = buildImportManifestForPack(
 input.packSlug,
 input.projectName,
 input.owner,
 input.selectedBundleSlugs
 );

 if (!manifestResult.data || manifestResult.error) {
 return {
 data: null,
 error: manifestResult.error
 };
 }

 return {
 data: {
 application: applicationResult.data,
 manifest: manifestResult.data,
 routeRequest: buildStarterPackRouteRequest({
 packSlug: input.packSlug,
 userId: input.userId,
 selectedBundleSlugs: input.sel...

import { z } from "zod";
import onboardingTaskGraphJson from "../setup/onboarding-task-graph.json";
import {
 recommendBuyerSegment,
 type BuyerSegment,
 type SegmentRecommendationInput
} from "../config/segments";
import {
 buildThemeFromBrandColor,
 getThemePreset,
 validateThemeAccessibility
} from "../config/themeEngine";

export type OnboardingEntryMode = "web" | "cli";
export type OnboardingTaskStatus = "pending" | "in_progress" | "completed" | "blocked";
export type OnboardingSessionStatus = "in_progress" | "blocked" | "completed";

const onboardingTaskDefinitionSchema = z.object({
 task_id: z.string().min(1),
 title: z.string().min(1),
 description: z.string().min(1),
 entry_modes: z.array(z.enum(["web", "cli"])),
 segments: z.array(z.enum(["solo", "business", "enterprise"])),
 preconditions: z.array(z.string()),
 inputs: z.array(z.string()),
 actions: z.array(z.string()),
 outputs: z.array(z.string()),
 failure_modes: z.array(z.string()),
 next: z.array(z.string())
});

const onboardingTaskGraphSchema = z.object({
 version: z.string().min(1),
 defaultTaskOrder: z.array(z.string().min(1)),
 tracks: z.object({
 solo: z.array(z.string().min(1)),
 business: z.array(z.string().min(1)),
 enterprise: z.array(z.string().min(1))
 }),
 tasks: z.array(onboardingTaskDefinitionSchema)
});

export type OnboardingTaskDefinition = z.infer<typeof onboardingTaskDefinitionSchema>;
export type OnboardingTaskGraph = z.infer<typeof onboardingTaskGraphSchema>;

export interface OnboardingEvidence {
 kind: "summary" | "metric" | "check" | "artifact";
 label: string;
 value: string;
 metadata?: Record<string, unknown>;
}

export interface OnboardingTaskRecord {
 id: string;
 taskKey: string;
 status: OnboardingTaskStatus;
 input: Record<string, unknown>;
 output: Record<string, unknown>;
 summary: string;
 error: Record<string, unknown> | null;
 evidence: OnboardingEvidence[];
 updatedAt: string;
}

export interface OnboardingSessionRecord {
 id: string;
 workspaceId: string | null;
 entryMode: OnboardingEntryMode;
 status: OnboardingSessionStatus;
 segmentRecommendation: BuyerSegment;
 metadata?: Record<string, unknown>;
 startedAt: string;
 completedAt: string | null;
 tasks: OnboardingTaskRecord[];
}

export interface CreateOnboardingSessionInput extends SegmentRecommendationInput {
 entryMode: OnboardingEntryMode;
 workspaceId?: string | null;
 segment?: BuyerSegment;
}

export interface OnboardingSessionProgress {
 completedTaskCount: number;
 blockedTaskCount: number;
 totalTaskCount: number;
 nextTaskKey: string | null;
 canPublish: boolean;
}

export interface OnboardingExecutionResult {
 session: OnboardingSessionRecord;
 task: OnboardingTaskRecord;
 nextTaskKeys: string[];
}

const onboardingTaskGraph = onboardingTaskGraphSchema.parse(onboardingTaskGraphJson);

function nowIso(): string {
 return new Date().toISOString();
}

function generateId(): string {
 if (typeof globalThis.crypto?.randomUUID === "function") {
 return globalThis.crypto.randomUUID();
 }

 return `onboarding-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function buildTaskRecord(taskKey: string): OnboardingTaskRecord {
 return {
 id: generateId(),
 taskKey,
 status: "pending",
 input: {},
 output: {},
 summary: "Not started.",
 error: null,
 evidence: [],
 updatedAt: nowIso()
 };
}

function makeSummary(label: string, detail: string): OnboardingEvidence {
 return {
 kind: "summary",
 label,
 value: detail
 };
}

function findTaskDefinition(taskKey: string): OnboardingTaskDefinition | null {
 return onboardingTaskGraph.tasks.find((task) => task.task_id === taskKey) ?? null;
}

function getTrackForSegment(segment: BuyerSegment): string[] {
 return onboardingTaskGraph.tracks[segment];
}

function arePreconditionsMet(
 session: OnboardingSessionRecord,
 taskDefinition: OnboardingTaskDefinition
): boolean {
 return taskDefinition.preconditions.every((precondition) =>
 session.tasks.some((task) => task.taskKey === precondition && task.status === "completed")
 );
}

function computeSessionStatus(session: OnboardingSessionRecord): OnboardingSessionStatus {
 if (session.tasks.some((task) => task.status === "blocked")) {
 return "blocked";
 }
 if (session.tasks.every((task) => task.status === "completed")) {
 return "completed";
 }
 return "in_progress";
}

function redactSecrets(input: Record<string, unknown>): Record<string, unknown> {
 return Object.fromEntries(
 Object.entries(input).map(([key, value]) => {
 if (
 key.toLowerCase().includes("key") ||
 key.toLowerCase().includes("secret") ||
 key.toLowerCase().includes("token")
 ) {
 return [key, value ? "[redacted]" : value];
 }
 return [key, value];
 })
 );
}

export function getOnboardingTaskGraph(): OnboardingTaskGraph {
 return onboardingTaskGraph;
}

export function getOnboardingTasksForSegment(segment: BuyerSegment): OnboardingTaskDefinition[] {
 const taskKeys = new Set(getTrackForSegment(segment));
 return onboardingTaskGraph.tasks.filter((task) => taskKeys.has(task.task_id));
}

export function createOnboardingSession(
 input: CreateOnboardingSessionInput
): OnboardingSessionRecord {
 const segmentRecommendation = input.segment ?? recommendBuyerSegment(input).segment;
 const track = getTrackForSegment(segmentRecommendation);
 const tasks: OnboardingTaskRecord[] = track.map((taskKey, index) => ({
 ...buildTaskRecord(taskKey),
 status: index === 0 ? "in_progress" : "pending",
 summary: index === 0 ? "Ready to start." : "Waiting on prerequisites."
 }));

 return {
 id: generateId(),
 workspaceId: input.workspaceId ?? null,
 entryMode: input.entryMode,
 status: "in_progress",
 segmentRecommendation,
 metadata: {},
 startedAt: nowIso(),
 completedAt: null,
 tasks
 };
}

export function getOnboardingProgress(
 session: OnboardingSessionRecord
): OnboardingSessionProgress {
 const completedTaskCount = session.tasks.filter((task) => task.status === "completed").length;
 const blockedTaskCount = session.tasks.filter((task) => task.status === "blocked").length;
 const nextTask =
 session.tasks.find((task) => task.status === "in_progress") ??
 session.tasks.find((task) => task.status === "pending");
 const publishTask = session.tasks.find((task) => task.taskKey === "publish_agent");

 return {
 completedTaskCount,
 blockedTaskCount,
 totalTaskCount: session.tasks.length,
 nextTaskKey: nextTask?.taskKey ?? null,
 canPublish: publishTask?.status === "completed"
 };
}

function promoteNextAvailableTask(session: OnboardingSessionRecord): OnboardingSessionRecord {
 const currentInProgress = session.tasks.some((task) => task.status === "in_progress");

 if (currentInProgress) {
 return session;
 }

 const nextTask = session.tasks.find((task) => {
 if (task.status !== "pending") {
 return false;
 }

 const definition = findTaskDefinition(task.taskKey);
 return definition ? arePreconditionsMet(session, definition) : false;
 });

 if (!nextTask) {
 return {
 ...session,
 status: computeSessionStatus(session),
 completedAt:
 session.tasks.every((task) => task.status === "completed") ? nowIso() : session.completedAt
 };
 }

 return {
 ...session,
 tasks: session.tasks.map((task) =>
 task.id === nextTask.id
 ? {
 ...task,
 status: "in_progress",
 summary: "Ready to start.",
 updatedAt: nowIso()
 }
 : task
 ),
 status: computeSessionStatus(session)
 };
}

function buildTaskOutcome(
 taskKey: string,
 input: Record<string, unknown>
): {
 status: OnboardingTaskStatus;
 output: Record<string, unknown>;
 summary: string;
 error: Record<string, unknown> | null;
 evidence: OnboardingEvidence[];
} {
 switch (taskKey) {
 case "recommend_segment": {
 const recommendation = recommendBuyerSegment(input as SegmentRecommendationInput);
 return {
 status: "completed",
 output: {
 segment_recommendation: recommendation.segment,
 segment_score: recommendation.score,
 breakdown: recommendation.breakdown
 },
 summary: `Recommended ${recommendation.segment} based on onboarding profile score ${recommendation.score}.`,
 error: null,
 evidence: [
 makeSummary("Segment", recommendation.segment),
 {
 kind: "metric",
 label: "Score",
 value: String(recommendation.score)
 }
 ]
 };
 }
 case "create_workspace": {
 const workspaceName = String(input.workspace_name ?? "");
 const agentName = String(input.agent_name ?? "");

 if (!workspaceName || !agentName) {
 return {
 status: "blocked",
 output: {},
 summary: "Workspace and agent names are required.",
 error: { code: "missing_workspace_or_agent_name" },
 evidence: [makeSummary("Blocker", "Provide both workspace and agent names.")]
 };
 }

 return {
 status: "completed",
 output: {
 workspace_status: "ready",
 agent_status: "ready",
 workspace_slug: workspaceName.toLowerCase().replace(/\s+/g, "-"),
 agent_slug: agentName.toLowerCase().replace(/\s+/g, "-"),
 next_recommended_step: "Create the repo and corpus container before importing files."
 },
 summary: `Workspace "${workspaceName}" and agent "${agentName}" are ready. Next create the repo and corpus container.`,
 error: null,
 evidence: [makeSummary("Workspace", workspaceName), makeSummary("Agent", agentName)]
 };
 }
 case "stage_corpus_container": {
 const repository = String(input.repository ?? "");
 const corpusContainer = String(input.corpus_container ?? "");
 const defaultBranch = String(input.default_branch ?? "main");
 const stagingMode = String(input.staging_mode ?? "guided");

 if (!repository || !corpusContainer) {
 return {
 status: "blocked",
 output: {},
 summary: "Repo and corpus staging needs both a repository reference and a container path.",
 error: { code: "missing_repo_container_inputs" },
